  `subj` STRING COMMENT 'Subject.',
  `opn_ts` TIMESTAMP COMMENT 'Opened at.',
  `cls_ts` TIMESTAMP COMMENT 'Closed at.',
  `csat` DOUBLE COMMENT 'Post-resolution CSAT 1–5; NULL if still open.',
  `rgn` STRING COMMENT 'Region.',
  `tkt_yr` INT COMMENT 'Ticket year.',
  `crt_ts` TIMESTAMP COMMENT 'Row create timestamp.',
  `upd_ts` TIMESTAMP COMMENT 'Row last-update timestamp.',
  `src_sys_cd` STRING COMMENT 'Source system code (ETL bookkeeping).',
  `etl_btch_id` BIGINT COMMENT 'ETL batch id.',
  `rec_eff_dt` DATE COMMENT 'Record effective date (SCD).',
  `del_flg` BOOLEAN COMMENT 'Soft-delete flag.',
  CONSTRAINT `pk_ods_svc_03_t_0320` PRIMARY KEY (`tkt_id`)
)
COMMENT 'Cleaned customer-support tickets (all years). priority P1 is critical. status=open means the incident is still unresolved. Includes the post-resolution CSAT (customer satisfaction) score for closed tickets, so use this for average-CSAT-by-year questions. This is the system of record for support-ticket questions — not bronze year shards, not HR tickets, not arch_hist.';

